// Command rbacdiff turns locally rendered RBAC YAML into the checked-in reference.
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"

	rbacv1 "k8s.io/api/rbac/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	utilyaml "k8s.io/apimachinery/pkg/util/yaml"
)

const introduction = `# RBAC reference

<!-- Generated by hack/rbac-diff.sh; edit the chart or hack/rbacdiff, not these tables. -->

This reference audits the default Helm render: release ` + "`tailnet-operator`" + `,
namespace ` + "`tailnet-system`" + `. It does not query a cluster or include grants from other installations.

## Scope and limitations

- ` + "`tailnet-operator-crds`" + ` reads Tailnet and TailnetIngress specs and writes their status subresources.
  It grants no CR spec writes and no CustomResourceDefinition-object reads.
- ` + "`tailnet-operator-workloads`" + ` manages tenant ingress children across all namespaces.
  Secrets, ConfigMaps, Deployments, NetworkPolicies and Events remain broadly accessible;
  Pods are read-only. The role split itself does not reduce permissions or provide tenant isolation.
- The HTTP issuer workflow adds Certificate get/create/patch/delete in all namespaces.
  The controller uses namespace-local requests without an informer. No Issuer, ClusterIssuer,
  CertificateRequest or CustomResourceDefinition-object access is granted.
- The namespaced Role keeps TailnetEgress reads/status writes, Services and leader-election Leases in the operator namespace.
  The egress cache remains namespace-scoped. No cluster-wide egress or Service access is granted.
- Finalizers-update authorization for each managed CR permits existing blocking owner references when
  OwnerReferencesPermissionEnforcement is enabled. Tailnet/TailnetIngress grants are cluster-wide;
  TailnetEgress remains operator-namespaced. No create/update/patch/delete grant on CR specs is added.
  This is an intentional permission addition, not a role-splitting-only change.
- The Role repeats the original workload permissions, including working Secret access, for the egress path.
  It does not repeat the additional Certificate grant.
  The workload ClusterRole already grants those permissions globally; the Role does not narrow them.
- Lease verbs remain get, list, watch, create, update and patch. Disabling leader election removes that rule.
- Default permissions contain no wildcards, non-resource URLs or resource-name restrictions.
  Kubernetes cannot restrict top-level create requests with ` + "`resourceNames`" + `.
  A create grant cannot be made name-isolated by adding that field.

## Reproduce and review

Run ` + "`bash hack/rbac-diff.sh`" + ` (or ` + "`--check`" + `) to fail on reference drift.
After reviewing an intentional RBAC change, run ` + "`bash hack/rbac-diff.sh --write`" + `.
The script requires Helm and Go, uses existing Go dependencies, and never needs yq or cluster access.
Both commands render chart defaults, not environment-specific values.

The effective namespace column follows bindings, not a ClusterRole's name or declaration scope.
Cluster-wide means all namespaces and any cluster-scoped resources named by the rule.
A RoleBinding limits its referenced role to that binding's namespace and cannot grant non-resource URL access.
Unbound roles and bindings without subjects grant nothing. Kubernetes adds grants; narrower roles cannot revoke broader permissions.
The bindings table identifies the subjects receiving each role's rules.

## Effective rules

| Role | Role namespace | Effective namespace(s) | API groups | Resources | Verbs | Resource names | Non-resource URLs |
| --- | --- | --- | --- | --- | --- | --- | --- |
`

type object struct {
	metav1.TypeMeta `json:",inline"`
	Metadata        metav1.ObjectMeta       `json:"metadata"`
	Rules           []rbacv1.PolicyRule     `json:"rules"`
	AggregationRule *rbacv1.AggregationRule `json:"aggregationRule"`
	RoleRef         rbacv1.RoleRef          `json:"roleRef"`
	Subjects        []rbacv1.Subject        `json:"subjects"`
}

func (o object) key() string {
	return o.Kind + "/" + o.Metadata.Namespace + "/" + o.Metadata.Name
}

func (o object) referenceKey() string {
	namespace := ""
	if o.RoleRef.Kind == "Role" {
		namespace = o.Metadata.Namespace
	}
	return o.RoleRef.Kind + "/" + namespace + "/" + o.RoleRef.Name
}

func parse(r io.Reader) (map[string]object, map[string]object, error) {
	roles, bindings := map[string]object{}, map[string]object{}
	decoder := utilyaml.NewYAMLOrJSONDecoder(r, 4096)
	for {
		var raw json.RawMessage
		if err := decoder.Decode(&raw); err == io.EOF {
			break
		} else if err != nil {
			return nil, nil, fmt.Errorf("decode manifest: %w", err)
		}
		if len(raw) == 0 {
			continue
		}
		var meta metav1.TypeMeta
		if err := json.Unmarshal(raw, &meta); err != nil {
			return nil, nil, err
		}
		if meta.APIVersion != rbacv1.SchemeGroupVersion.String() {
			continue
		}
		var dst map[string]object
		switch meta.Kind {
		case "Role", "ClusterRole":
			dst = roles
		case "RoleBinding", "ClusterRoleBinding":
			dst = bindings
		default:
			continue
		}
		var o object
		if err := json.Unmarshal(raw, &o); err != nil {
			return nil, nil, err
		}
		if o.Metadata.Name == "" || ((o.Kind == "Role" || o.Kind == "RoleBinding") && o.Metadata.Namespace == "") {
			return nil, nil, fmt.Errorf("%s requires explicit name and namespace", o.Kind)
		}
		if strings.HasPrefix(o.Kind, "Cluster") && o.Metadata.Namespace != "" {
			return nil, nil, fmt.Errorf("%s must not have a namespace", o.key())
		}
		if o.AggregationRule != nil {
			return nil, nil, fmt.Errorf("%s: aggregated roles cannot be resolved from this render alone", o.key())
		}
		if _, exists := dst[o.key()]; exists {
			return nil, nil, fmt.Errorf("duplicate %s", o.key())
		}
		dst[o.key()] = o
	}
	if len(roles) == 0 {
		return nil, nil, fmt.Errorf("no RBAC roles in input")
	}
	for _, b := range bindings {
		if b.RoleRef.APIGroup != rbacv1.GroupName || (b.RoleRef.Kind != "Role" && b.RoleRef.Kind != "ClusterRole") || (b.Kind == "ClusterRoleBinding" && b.RoleRef.Kind != "ClusterRole") {
			return nil, nil, fmt.Errorf("%s: invalid roleRef", b.key())
		}
		if _, exists := roles[b.referenceKey()]; !exists {
			return nil, nil, fmt.Errorf("%s references missing %s", b.key(), b.referenceKey())
		}
	}
	return roles, bindings, nil
}

// Sort both table rows and values within cells so YAML document/rule/list order
// cannot create reference drift. Do not collapse rules: resourceNames matter.
func cell(values []string, empty string) string {
	if len(values) == 0 {
		return empty
	}
	values = append([]string(nil), values...)
	sort.Strings(values)
	for i, v := range values {
		if v == "" {
			v = "(core)"
		}
		values[i] = "`" + strings.NewReplacer("|", "&#124;", "`", "&#96;", "\n", " ", "\r", " ").Replace(v) + "`"
	}
	return strings.Join(values, ", ")
}

func text(value string) string {
	if value == "" {
		return "—"
	}
	return cell([]string{value}, "—")
}

func row(columns ...string) string {
	return "| " + strings.Join(columns, " | ") + " |\n"
}

func generate(r io.Reader) (string, error) {
	roles, bindings, err := parse(r)
	if err != nil {
		return "", err
	}
	scopes := map[string]map[string]bool{}
	var bindingRows []string
	for _, b := range bindings {
		scope := b.Metadata.Namespace
		if b.Kind == "ClusterRoleBinding" {
			scope = "cluster-wide"
		}
		key := b.referenceKey()
		if scopes[key] == nil {
			scopes[key] = map[string]bool{}
		}
		if len(b.Subjects) > 0 {
			scopes[key][scope] = true
		}
		var subjects []string
		for _, s := range b.Subjects {
			namespace := s.Namespace
			if s.Kind == "ServiceAccount" && namespace == "" {
				namespace = b.Metadata.Namespace
			}
			subjects = append(subjects, s.Kind+"/"+namespace+"/"+s.Name+" (apiGroup="+s.APIGroup+")")
		}
		bindingRows = append(bindingRows, row(text(b.Kind+"/"+b.Metadata.Name), text(b.Metadata.Namespace), text(key), cell(subjects, "none")))
	}
	var ruleRows []string
	for key, role := range roles {
		var effective []string
		for scope := range scopes[key] {
			effective = append(effective, scope)
		}
		rules := role.Rules
		if len(rules) == 0 {
			rules = []rbacv1.PolicyRule{{}}
		}
		for _, rule := range rules {
			ruleScopes := effective
			if len(rule.NonResourceURLs) > 0 {
				ruleScopes = nil
				if scopes[key]["cluster-wide"] {
					ruleScopes = []string{"cluster-wide"}
				}
			}
			ruleRows = append(ruleRows, row(text(role.Kind+"/"+role.Metadata.Name), text(role.Metadata.Namespace), cell(ruleScopes, "not granted"), cell(rule.APIGroups, "—"), cell(rule.Resources, "—"), cell(rule.Verbs, "—"), cell(rule.ResourceNames, "all names"), cell(rule.NonResourceURLs, "—")))
		}
	}
	sort.Strings(ruleRows)
	sort.Strings(bindingRows)
	return introduction + strings.Join(ruleRows, "") + "\n## Bindings\n\n" +
		"| Binding | Namespace | Role reference (kind/namespace/name) | Subjects (kind/namespace/name, API group) |\n" +
		"| --- | --- | --- | --- |\n" + strings.Join(bindingRows, ""), nil
}

func main() {
	output, err := generate(os.Stdin)
	if err == nil {
		_, err = io.WriteString(os.Stdout, output)
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, "rbacdiff:", err)
		os.Exit(1)
	}
}
